use std :: fs ; use std :: io :: { BufRead , BufReader } ; use std :: path :: PathBuf ; use std :: process :: Stdio ; use anyhow :: { Context , Result } ; use clap :: CommandFactory ; use clap_complete :: generate ; use clap_complete :: shells :: Zsh ; use include_dir :: { Dir , include_dir } ; use crate :: cli :: Cli ; use std :: io :: Write ; use std :: sync :: { LazyLock , Mutex } ; use super :: * ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use tempfile :: TempDir ; use tempfile :: TempDir ; use tempfile :: TempDir ; use tempfile :: TempDir ; use tempfile :: TempDir ; # [doc = " Generates the complete zsh plugin by combining embedded files and clap"] # [doc = " completions"] pub fn generate_zsh_plugin () -> Result < String > { let mut output = String :: new () ; for file in forge_embed :: files (& ZSH_PLUGIN_LIB) { let content = super :: normalize_script (std :: str :: from_utf8 (file . contents ()) ?) ; for line in content . lines () { let trimmed = line . trim () ; if ! trimmed . is_empty () && ! trimmed . starts_with ('#') { output . push_str (line) ; output . push ('\n') ; } } } let mut cmd = Cli :: command () ; let mut completions = Vec :: new () ; generate (Zsh , & mut cmd , "forge" , & mut completions) ; let completions_str = String :: from_utf8 (completions) ? ; output . push_str ("\n# --- Clap Completions ---\n") ; output . push_str (& completions_str) ; output . push_str ("\n_FORGE_PLUGIN_LOADED=$(date +%s)\n") ; Ok (output) }